begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor_id uuid,competitor_id uuid,request_id uuid,source jsonb,model jsonb,preview jsonb);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid(),null,null,'{"pricingBasis":"monthly_rent_usd","units":[{"unit_type":"A1","bedrooms":1,"bathrooms":null,"sqft_min":null,"sqft_max":null,"rent_min":1200,"rent_max":null,"deposit":null,"available_count":null,"move_in_specials":null,"evidence":[{"field":"unit_type","quote":"A1"},{"field":"bedrooms","quote":"1 bedroom"},{"field":"rent_min","quote":"$1200 monthly rent in USD"}]}],"notes":null}');
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision extraction rollback fixture'from fixture union all select other_property,'22222222-2222-2222-2222-222222222222'::uuid,'MarketVision other extraction rollback fixture'from fixture;
insert into public.competitors(id,property_id,name,property_type)select competitor_id,property_id,'Extraction fixture competitor','multifamily'from fixture;
insert into public.competitor_units(competitor_id,unit_type,bedrooms,rent_min,available_count)select competitor_id,'Unselected type',2,1500,3 from fixture;
update fixture set source=jsonb_build_object('competitorId',competitor_id,'sourceVersion',1,'content','A1 has 1 bedroom. Starting at $1200 monthly rent in USD. Contact the property to confirm availability.','sourceUrl','','effectiveAt',null,'reason','Reviewed source for isolated pricing extraction');
update fixture set model=jsonb_build_object('model','gpt-4o-mini','promptVersion','pricing-v2','source',jsonb_build_object('content',source->>'content','propertyType','multifamily'),'systemPrompt','Isolated model contract fixture','userPrompt',source->>'content','maxTokens',8000);
do $$declare f fixture;r jsonb;claim jsonb;receipt jsonb;request_version integer;preview_hash text;command uuid;payload jsonb;begin select * into f from fixture;
 perform pg_temp.check(not has_function_privilege('authenticated','public.begin_marketvision_extraction(uuid,uuid,uuid,jsonb,jsonb)','execute')and not has_table_privilege('authenticated','public.marketvision_extraction_requests','select'),'direct clients cannot forge invocations or read raw source evidence');
 perform pg_temp.check(public.begin_marketvision_extraction(f.request_id,f.property_id,gen_random_uuid(),f.source,f.model)->>'state'='forbidden','source requests require a current property actor');
 r:=public.begin_marketvision_extraction(f.request_id,f.property_id,f.actor_id,f.source,f.model);perform pg_temp.check(r->>'state'='queued','exact source and model contract are saved before execution');
 perform pg_temp.check((select state='queued'and claim_token is null and model_input=f.model from public.marketvision_extraction_requests where id=f.request_id),'request creation does not claim a model invocation');
 perform pg_temp.check(public.begin_marketvision_extraction(f.request_id,f.property_id,f.actor_id,f.source,'{}')->>'state'='queued'and(select count(*)=1 from public.shared_jobs where id=f.request_id),'lost creation responses recover the original saved recipe');
 perform pg_temp.check(public.begin_marketvision_extraction(f.request_id,f.property_id,f.actor_id,f.source||'{"reason":"different source request"}',f.model)->>'state'='request_conflict','request identity cannot replace reviewed content');
 perform pg_temp.check(public.begin_marketvision_extraction(gen_random_uuid(),f.property_id,f.actor_id,f.source,f.model)->>'state'='busy','one open extraction prevents concurrent duplicate model requests');
 perform pg_temp.check((select shared_job_ref=f.request_id from public.shared_action_events where id=f.request_id),'operator request links to its retained execution job');
 claim:=public.claim_marketvision_extraction(f.request_id);perform pg_temp.check(claim->>'state'='invoke_once','the first worker receives one invocation intent');
 perform pg_temp.check(public.claim_marketvision_extraction(f.request_id)->>'state'='running','a concurrent or restarted worker cannot invoke again');
 perform pg_temp.check((select actor_id is null and service_principal='marketvision.extraction'and before_state->>'state'='queued' from public.shared_action_events where shared_job_ref=f.request_id and action='market.extraction.started'),'actual service principal and transition are recorded without a fabricated human');
 receipt:=jsonb_build_object('status','received','content',f.preview::text,'finishReason','stop');
 perform pg_temp.check(public.record_marketvision_extraction_result(f.request_id,gen_random_uuid(),receipt)->>'state'='claim_mismatch','wrong invocation token cannot replace a result');
 perform pg_temp.check(public.record_marketvision_extraction_result(f.request_id,(claim->>'claimToken')::uuid,receipt)->>'requestState'='result_ready','raw model receipt persists before parsing');
 perform pg_temp.check(public.record_marketvision_extraction_result(f.request_id,(claim->>'claimToken')::uuid,receipt)->>'state'='replayed','receipt retries are idempotent');
 perform pg_temp.check(public.record_marketvision_extraction_result(f.request_id,(claim->>'claimToken')::uuid,receipt||'{"finishReason":"length"}')->>'state'='result_conflict','a different late model result cannot replace the retained receipt');
 perform pg_temp.check(public.prepare_marketvision_extraction_preview(f.request_id,public.crm_configuration_hash(receipt),f.preview)->>'state'='saved','exact retained result becomes a reviewable preview');
 perform pg_temp.check((select count(*)=1 from public.competitor_units where competitor_id=f.competitor_id),'preparing a preview does not mutate any units');
 select version,r.preview_hash into request_version,preview_hash from public.marketvision_extraction_requests r where id=f.request_id;
 payload:=jsonb_build_object('extractionId',f.request_id,'expectedVersion',request_version,'previewHash',preview_hash,'confirmedMonthlyRentUsd',true,'selection',jsonb_build_array(jsonb_build_object('sourceIndex',0,'values',((f.preview->'units'->0)-'evidence')||'{"rent_min":1250}')),'reason','Corrected quoted price after reviewing full current source');command:=gen_random_uuid();
 perform pg_temp.check(public.apply_marketvision_extraction(command,f.other_property,f.actor_id,payload)->>'state'='not_found','application cannot escape the selected property');
 update public.competitor_units set rent_min=1600 where competitor_id=f.competitor_id;
 perform pg_temp.check(public.apply_marketvision_extraction(command,f.property_id,f.actor_id,payload)->>'state'='stale_source','another unit/provider change blocks outdated source application');
 perform public.control_marketvision_extraction(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('action','rebase','extractionId',f.request_id,'expectedVersion',request_version,'reason','Review current unit baseline after source change'));
 select version,r.preview_hash into request_version,preview_hash from public.marketvision_extraction_requests r where id=f.request_id;
 perform pg_temp.check(public.apply_marketvision_extraction(command,f.property_id,f.actor_id,payload||jsonb_build_object('expectedVersion',request_version))->>'state'='stale_preview','refreshed baseline invalidates the previous reviewed preview hash');
 payload:=payload||jsonb_build_object('expectedVersion',request_version,'previewHash',preview_hash);r:=public.apply_marketvision_extraction(command,f.property_id,f.actor_id,payload);
 perform pg_temp.check(r->>'state'='saved'and r->>'savedUnits'='1'and r->'modelInvoked'='false'::jsonb,'reviewed corrections apply without calling the model again');
 perform pg_temp.check((select count(*)=2 from public.competitor_units where competitor_id=f.competitor_id)and(select rent_min=1600 from public.competitor_units where competitor_id=f.competitor_id and unit_type='Unselected type'),'unselected unit types and their values are preserved');
 perform pg_temp.check((select rent_min=1250 and bathrooms is null and available_count is null and capture_id=f.request_id from public.competitor_units where competitor_id=f.competitor_id and unit_type='A1'),'approved values preserve unknowns and link exact source provenance');
 perform pg_temp.check((select source_type='manual'and raw_ref='marketvision_extraction_requests:'||f.request_id::text and effective_at is null from public.market_source_captures where id=f.request_id),'operator paste is distinct from provider capture and unknown source date remains unknown');
 perform pg_temp.check((select last_scraped_at is null from public.competitors where id=f.competitor_id),'manual extraction does not pretend a fresh provider scrape occurred');
 perform pg_temp.check(public.apply_marketvision_extraction(command,f.property_id,f.actor_id,payload)->>'state'='replayed'and(select count(*)=1 from public.competitor_price_history where capture_id=f.request_id),'lost application replies recover once without duplicate price observations');
 perform pg_temp.check((select raw_result=receipt and preview=f.preview and state='completed'from public.marketvision_extraction_requests where id=f.request_id),'original model output survives operator corrections');
 perform pg_temp.check((select input->'selection'->0->'values'->>'rent_min'='1250'and before_state->'preview'->'units'->0->>'rent_min'='1200'from public.marketvision_decisions where id=command),'private decision retains original proposal and corrected applied values for later evaluation');
 perform pg_temp.check(public.control_marketvision_extraction(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('action','recover','extractionId',f.request_id,'expectedVersion',request_version+1,'reason','Try restarting closed work'))->>'state'='closed_request','completed source application cannot restart');
 perform pg_temp.check(public.read_marketvision_extractions(f.other_property,f.actor_id,f.competitor_id,f.request_id)->>'state'='not_found','source reads are property scoped');
 begin update public.marketvision_extraction_requests set input='{}'where id=f.request_id;raise exception 'expected immutable input';exception when others then if sqlerrm='expected immutable input' then raise;end if;end;
 perform pg_temp.check((select input=f.source from public.marketvision_extraction_requests where id=f.request_id),'raw source and model input remain immutable');
end$$;
do $$declare f fixture;rid uuid:=gen_random_uuid();claim jsonb;r jsonb;version integer;payload jsonb;receipt jsonb;begin select * into f from fixture;
 perform public.begin_marketvision_extraction(rid,f.property_id,f.actor_id,f.source,f.model);claim:=public.claim_marketvision_extraction(rid);
 select x.version into version from public.marketvision_extraction_requests x where id=rid;
 payload:=jsonb_build_object('action','stop','extractionId',rid,'expectedVersion',version,'reason','Stop before any source application');r:=public.control_marketvision_extraction(gen_random_uuid(),f.property_id,f.actor_id,payload);
 perform pg_temp.check(r->>'requestState'='stopped','operator can stop an in-flight request without claiming model cancellation');
 receipt:=jsonb_build_object('status','received','content',f.preview::text,'finishReason','stop');perform public.record_marketvision_extraction_result(rid,(claim->>'claimToken')::uuid,receipt);
 perform pg_temp.check((select state='stopped'and raw_result=receipt from public.marketvision_extraction_requests where id=rid),'late model receipt is retained but cannot reopen stopped work');
 perform pg_temp.check(public.prepare_marketvision_extraction_preview(rid,public.crm_configuration_hash(receipt),f.preview)->>'state'='stopped','late receipt cannot mutate stopped source previews');
 rid:=gen_random_uuid();perform public.begin_marketvision_extraction(rid,f.property_id,f.actor_id,f.source,f.model);claim:=public.claim_marketvision_extraction(rid);perform public.record_marketvision_extraction_result(rid,(claim->>'claimToken')::uuid,'{"status":"uncertain","errorCode":"model_uncertain"}');
 perform pg_temp.check(public.claim_marketvision_extraction(rid)->>'state'='held','uncertain model outcomes never repeat the model invocation');
 rid:=gen_random_uuid();perform public.begin_marketvision_extraction(rid,f.property_id,f.actor_id,f.source,f.model);claim:=public.claim_marketvision_extraction(rid);receipt:=jsonb_build_object('status','received','content','{broken','finishReason','stop');perform public.record_marketvision_extraction_result(rid,(claim->>'claimToken')::uuid,receipt);
 perform pg_temp.check(public.prepare_marketvision_extraction_preview(rid,public.crm_configuration_hash(receipt),null,'invalid_output')->>'state'='held','invalid structured output is held without partial unit updates');
 perform pg_temp.check((select count(*)=2 from public.competitor_units where competitor_id=f.competitor_id),'failed and stopped requests leave the approved unit set intact');
end$$;
-- Existing scheduled maintenance must respect manual-only and deferred next-run preferences.
insert into public.scrape_config(property_id,is_enabled,scrape_frequency,last_run_at,next_run_at)select property_id,true,'manual',null,null from fixture;
select pg_temp.check(not exists(select 1 from jsonb_array_elements(public.claim_phase_four_maintenance('competitors',5))j where j->>'property_id'=f.property_id::text),'manual-only monitoring is not claimed by the scheduler')from fixture f;
update public.scrape_config set scrape_frequency='daily',next_run_at=now()+interval '1 day'where property_id=(select property_id from fixture);
select pg_temp.check(not exists(select 1 from jsonb_array_elements(public.claim_phase_four_maintenance('competitors',5))j where j->>'property_id'=f.property_id::text),'newly deferred monitoring is not claimed before its next run')from fixture f;
-- Extended extraction qualification: failed later candidates roll back earlier writes and evidence.
do $$declare f fixture;rid uuid:=gen_random_uuid();claim jsonb;receipt jsonb;preview jsonb;payload jsonb;command uuid:=gen_random_uuid();r jsonb;cursor_id uuid;i integer;before_units jsonb;begin select * into f from fixture;
 preview:=jsonb_set(f.preview,'{units}',jsonb_build_array(f.preview->'units'->0,f.preview->'units'->0));
 perform public.begin_marketvision_extraction(rid,f.property_id,f.actor_id,f.source,f.model);claim:=public.claim_marketvision_extraction(rid);receipt:=jsonb_build_object('status','received','content',preview::text,'finishReason','stop');perform public.record_marketvision_extraction_result(rid,(claim->>'claimToken')::uuid,receipt);perform public.prepare_marketvision_extraction_preview(rid,public.crm_configuration_hash(receipt),preview);
 select jsonb_build_object('extractionId',id,'expectedVersion',version,'previewHash',preview_hash,'confirmedMonthlyRentUsd',true,'reason','Review all selected source values together','selection',jsonb_build_array(jsonb_build_object('sourceIndex',0,'values',((f.preview->'units'->0)-'evidence')||'{"rent_min":1800}'),jsonb_build_object('sourceIndex',1,'values',((f.preview->'units'->0)-'evidence')||'{"unit_type":"Invalid second type","bedrooms":-1}')))into payload from public.marketvision_extraction_requests where id=rid;
 before_units:=public.marketvision_competitor_context(f.property_id,f.competitor_id)->'units';
 begin perform public.apply_marketvision_extraction(command,f.property_id,f.actor_id,payload);raise exception 'expected rejected second candidate';exception when others then if sqlerrm='expected rejected second candidate' then raise;end if;end;
 perform pg_temp.check(public.marketvision_competitor_context(f.property_id,f.competitor_id)->'units'=before_units,'a rejected later candidate rolls back prior unit changes');
 perform pg_temp.check(not exists(select 1 from public.market_source_captures where id=rid)and not exists(select 1 from public.market_observations where capture_id=rid)and not exists(select 1 from public.competitor_price_history where capture_id=rid),'a rejected batch leaves no partial capture or price evidence');
 perform pg_temp.check(not exists(select 1 from public.marketvision_decisions where id=command)and not exists(select 1 from public.shared_action_events where id=command)and(select state='preview_ready'from public.marketvision_extraction_requests where id=rid),'failed application records no false success and remains reviewable');
 perform public.control_marketvision_extraction(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('action','stop','extractionId',rid,'expectedVersion',(payload->>'expectedVersion')::integer,'reason','Close isolated rollback qualification'));
 for i in 1..22 loop
  rid:=gen_random_uuid();r:=public.begin_marketvision_extraction(rid,f.property_id,f.actor_id,f.source||jsonb_build_object('reason','History qualification source '||i::text),f.model);
  perform public.control_marketvision_extraction(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('action','stop','extractionId',rid,'expectedVersion',1,'reason','Close history qualification source'));
 end loop;
 r:=public.read_marketvision_extractions(f.property_id,f.actor_id,f.competitor_id);cursor_id:=(r->>'nextCursor')::uuid;
 perform pg_temp.check(jsonb_array_length(r->'requests')=20 and cursor_id is not null,'source history explicitly pages beyond twenty requests');
 perform pg_temp.check(jsonb_array_length(public.read_marketvision_extractions(f.property_id,f.actor_id,f.competitor_id,null,cursor_id)->'requests')=7,'source history cursor retains every older source request');
 perform pg_temp.check(public.read_marketvision_extractions(f.property_id,f.actor_id,f.competitor_id,null,gen_random_uuid())->>'state'='cursor_changed','unrelated history cursors are rejected');
 update public.profiles set org_id=null where id=f.actor_id;
 perform pg_temp.check(public.read_marketvision_extractions(f.property_id,f.actor_id,f.competitor_id,f.request_id)->>'state'='forbidden'and public.begin_marketvision_extraction(f.request_id,f.property_id,f.actor_id,f.source,f.model)->>'state'='forbidden','lost replies and private source reads recheck current access');
 update public.profiles set org_id='22222222-2222-2222-2222-222222222222'where id=f.actor_id;
end$$;
select count(*)as passed_assertions from checks;
rollback;
